      "informacoes": [
        {
          "citacao": "A Liberação de engenharia está prevista para D40",
          "motivo": "valor_divergente",
          "correto_seria": "A Liberação de engenharia está prevista para D42."
        },
        {
          "citacao": "disponibilidade do protótipo para D25",
          "motivo": "valor_divergente",
          "correto_seria": "A disponibilidade do protótipo é D27."
        },
        {
          "citacao": "O caminho crítico passa pela entrega da GearWorks em D20",
          "motivo": "premissa_alterada",
          "correto_seria": "O caminho crítico passa pela entrega da MetalForm em D22."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_A.SUPRIMENTOS",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "2 dias de folga",
          "motivo": "valor_divergente",
          "correto_seria": "A MotorTech tem 4 dias de folga."
        },
        {
          "citacao": "sem folga",
          "motivo": "valor_divergente",
          "correto_seria": "A GearWorks tem 2 dias de folga."
        },
        {
          "citacao": "entrega carcaça, eixo, rolamento e vedação em D17",
          "motivo": "valor_divergente",
          "correto_seria": "A MetalForm entrega carcaça, eixo, rolamento e vedação em D22."
        },
        {
          "citacao": "3 dias de folga",
          "motivo": "valor_divergente",
          "correto_seria": "A MetalForm tem 0 dias de folga."
        },
        {
          "citacao": "SensePro entrega o sensor em D16, com 4 dias de folga",
          "motivo": "valor_divergente",
          "correto_seria": "A SensePro entrega o sensor em D16, com 6 dias de folga."
        },
        {
          "citacao": "apenas 1 dia de folga",
          "motivo": "valor_divergente",
          "correto_seria": "O fornecedor da placa de controle e do chicote tem 3 dias de folga."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_A.ENGENHARIA",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "a montagem do protótipo, de D20 a D25",
          "motivo": "valor_divergente",
          "correto_seria": "A montagem do protótipo ocorre de D22 a D27."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_A.TESTES",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "Todos os testes começam em D25",
          "motivo": "valor_divergente",
          "correto_seria": "Todos os testes começam em D27."
        },
        {
          "citacao": "carga, 4 dias, até D29",
          "motivo": "valor_divergente",
          "correto_seria": "O teste de carga dura 4 dias e termina em D31."
        },
        {
          "citacao": "térmico, 6 dias, até D31",
          "motivo": "valor_divergente",
          "correto_seria": "O teste térmico dura 6 dias e termina em D33."
        },
        {
          "citacao": "vida, 10 dias, até D35",
          "motivo": "valor_divergente",
          "correto_seria": "O teste de vida dura 10 dias e termina em D37."
        },
        {
          "citacao": "vedação, 3 dias, até D28",
          "motivo": "valor_divergente",
          "correto_seria": "O teste de vedação dura 3 dias e termina em D30."
        },
        {
          "citacao": "compatibilidade eletromagnética, 5 dias, até D30",
          "motivo": "valor_divergente",
          "correto_seria": "O teste de compatibilidade eletromagnética dura 5 dias e termina em D32."
        },
        {
          "citacao": "deve ser concluída em D35",
          "motivo": "valor_divergente",
          "correto_seria": "A validação deve ser concluída em D37."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_A.CUSTOS",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "O orçamento total é de R$ 152.000,00",
          "motivo": "valor_divergente",
          "correto_seria": "O custo total após o evento é de R$ 152.600,00."
        }
      ],
      "observacao": ""
    },
