          "motivo": "premissa_alterada",
          "correto_seria": "O projeto está 2 dias atrasado em relação à linha de base, com liberação prevista para D42."
        },
        {
          "citacao": "sem risco no caminho crítico",
          "motivo": "premissa_alterada",
          "correto_seria": "A entrega da MetalForm em D22 agora determina o caminho crítico e atrasa o projeto."
        },
        {
          "citacao": "fim da sexta semana",
          "motivo": "valor_divergente",
          "correto_seria": "A liberação está prevista para D42, no início da sétima semana."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_B.SUPRIMENTOS",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "Todas as entregas de fornecedores estão programadas para a terceira semana",
          "motivo": "valor_divergente",
          "correto_seria": "A entrega da MetalForm é em D22, na quarta semana; as demais entregas de fornecedores permanecem na terceira semana."
        },
        {
          "citacao": "O fornecedor do redutor é o último a entregar, no fim dessa semana",
          "motivo": "premissa_alterada",
          "correto_seria": "A MetalForm é a última a entregar, em D22, na primeira metade da quarta semana."
        }
      ],
      "observacao": ""
